#!/usr/bin/env node
/**
 * Merges the two link indexes of the Ignite UI for jQuery API reference into the one registry the
 * jQuery doc set reads, src/data/api-link-index/jquery/<name>.json:
 *
 * - the JavaScript API (`api-docs` platform `jquery`, package `ignite-ui`);
 * - the .NET API of the MVC, ASP.NET Core and Documents assemblies (`api-docs` platform
 *   `jquery-aspnet`, one package per assembly).
 *
 * Both are generated by api-docs in the registry shape the other platforms use
 * (`{ platform, version, packages, packageVersions, symbols }`, each symbol `{ p, u, k, m }`).
 * A name that exists in more than one package (`GridModel` in MVC and ASP.NET Core, `Workbook`
 * in JavaScript and in Documents.Excel) is stored the way the other registries store duplicates:
 * as an array of entries under the one key, which `ApiLink` tells apart by `pkg`.
 *
 * Usage:
 *   node docs/jquery/scripts/merge-api-link-index.mjs \
 *     --js=<api-docs dist>/en/api/jquery/api-link-index/latest.json \
 *     --net=<api-docs dist>/en/api/jquery-aspnet/api-link-index/latest.json \
 *     [--name=staging-latest]
 *
 * Writes src/data/api-link-index/jquery/<name>.json and lists it in the registry manifest when the
 * name is `staging-latest` (the manifest lists the staging snapshots). The output is sorted, so the
 * same inputs always give the same file.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const args = Object.fromEntries(process.argv.slice(2).map(a => {
    const [k, ...v] = a.replace(/^--/, '').split('=');
    return [k, v.join('=')];
}));

if (!args.js || !args.net) {
    console.error('Usage: merge-api-link-index.mjs --js=<jquery latest.json> --net=<jquery-aspnet latest.json> [--name=staging-latest]');
    process.exit(2);
}
const name = args.name || 'staging-latest';
const read = file => JSON.parse(fs.readFileSync(file, 'utf8').replace(/^﻿/, ''));
const sources = [read(args.js), read(args.net)];

const symbols = new Map();
const packages = new Set();
const packageVersions = {};
for (const source of sources) {
    for (const p of source.packages ?? []) packages.add(p);
    Object.assign(packageVersions, source.packageVersions ?? {});
    for (const [key, value] of Object.entries(source.symbols ?? {})) {
        if (!symbols.has(key)) symbols.set(key, []);
        symbols.get(key).push(...[].concat(value));
    }
}

const byPackageThenUrl = (a, b) => (a.p ?? '').localeCompare(b.p ?? '') || a.u.localeCompare(b.u);
const sortedSymbols = {};
let duplicates = 0;
for (const key of [...symbols.keys()].sort()) {
    const entries = symbols.get(key).sort(byPackageThenUrl);
    if (entries.length > 1) duplicates++;
    sortedSymbols[key] = entries.length === 1 ? entries[0] : entries;
}

const merged = {
    platform: 'jquery',
    version: 'latest',
    packages: [...packages].sort(),
    packageVersions: Object.fromEntries(Object.entries(packageVersions).sort(([a], [b]) => a.localeCompare(b))),
    symbols: sortedSymbols,
};

const outDir = path.join(repoRoot, 'src', 'data', 'api-link-index', 'jquery');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, `${name}.json`), `${JSON.stringify(merged)}\n`);

if (name === 'staging-latest') {
    const manifestFile = path.join(repoRoot, 'src', 'data', 'api-link-index', 'manifest.json');
    const manifest = read(manifestFile);
    const entry = `jquery/${name}.json`;
    if (!manifest.files.includes(entry)) {
        // Inserted in name order without reordering the existing entries.
        const at = manifest.files.findIndex(file => file > entry);
        manifest.files.splice(at === -1 ? manifest.files.length : at, 0, entry);
        fs.writeFileSync(manifestFile, `${JSON.stringify(manifest, null, 4)}\n`);
    }
}

console.log(`jquery/${name}.json: ${Object.keys(sortedSymbols).length} names, ${duplicates} in more than one package, packages ${merged.packages.join(', ')}`);
